Please give some indication of what this is, and clean up the definition.

Something like

// Struct representing the id, the value, and the type.
using statistic = std::tuple<std::string, std::string, double, uint64_t>;
// Object representing multiple independent statistics
using statistics_list = std::vector<statistic>;
// Object representing an an "Id" and a list of statistics for that Id
using stats_type = std::tuple<uint64_t, values_type>;

std::optional<stats_type> statistics;
